"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "어느 방이든: 원정 부대 HP +{0}%. “의료” 방이면: 병원 회복량 +{1}%, 리더가 매일 {2}% 추가 회복.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "어느 방이든: 설계도 드롭률 +{0}%. “SF” 방이면: 기지 매일 영혼 조각 +{1}.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "어느 방이든: 설계도 드롭률 +{0}%. “단조” 방이면: 제작 시 {1}% 확률로 하나 더.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "어느 방이든: 기지 매일 영혼 조각 +{0}. “마법” 방이면: 기지 매일 영혼 조각 추가 +{1}.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "어느 방이든: 기지 매일 물자 +{0}. “병참” 방이면: 이 방 자체 효과 ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "어느 방이든: 기지 매일 물자 +{0}, 리더가 매일 경험치 {1} 획득. “병참 / 자연” 방이면: 이 방 자체 효과 ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "어느 방이든: 유물 제작 비용 -{0}%. “단조 / 무기” 방이면: 단조: {1}% 확률로 품질 +{2}; 무기: 피해 +{3}%.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "어느 방이든: 건설 시간 절반, 완공 시 물자 {0}% 반환. “불가사의” 방이면: 반환율 {1}%로 상승.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "어느 방이든: 모든 방어탑 피해 +{0}%. “무기” 방이면: 사거리 +{1}, 공격 속도 +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "어느 방이든: 굴착 비용 -{0}%. “특수” 방이면: 모든 건설 기간 -{1}일.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "어느 방이든: 전투마다 시작 포인트 배율 +{0}. “단조” 방이면: 제작한 유물 품질 항상 +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "어느 방이든: 리더 스킬 쿨타임 {0}지점 감소. “운세” 방이면: 원정 시작 시 지원 아이템 {1}개 추가 (최소 “영웅” 효과).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "어느 방이든: 리더 공격력 +{0}%. “무기” 방이면: 피해 +{1}%, 공격마다 연쇄 번개 발사 (적 {2}명에게 튐).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "어느 방이든: 리더가 매일 HP {0}% 회복 (병원 불필요). “의료 / 수역” 방이면: 병원 회복량 +{1}%; 수역 무기 사거리 +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "어느 방이든: 리더가 매일 경험치 {0} 획득. “생산” 방이면: 이 방 자체 산출 ×{1}.",
