"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "앞에는 “묘지”: 안개가 가장 짙은 곳은 마을 밖 묘지다. 새 무덤이 밤마다 늘어난다.",
"前面是「总装车间」：工厂最后造出来的东西，把工厂里的人都装了进去。": "앞에는 “조립장”: 공장이 마지막으로 만든 것은 공장 사람들을 모두 그 안에 조립해 넣었다.",
"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "앞에는 “수술실”: 원장은 수술이 성공적이었다고 한다. 환자가 아직 깨어나지 않았을 뿐.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "앞에는 “해저”: 항구 아래에는 또 하나의 도시가 있고, 그 성문은 입이다.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "앞에는 “지식의 고목”: 고목은 숲에서 일어난 모든 일을 기억한다. 더는 아무것도 기억하고 싶지 않다.",
"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "앞에는 “엘프 여왕”: 여왕은 달의 연못가에서 삼백 년을 기다렸다. 그녀는 당신이 바로 기다리던 사람이라고 말한다.",
"前面是「马戏大棚」：大棚里的笑声从来没停过，只是再也没有观众。": "앞에는 “서커스 천막”: 천막 안의 웃음소리는 한 번도 멈춘 적이 없다. 다만 이제 관객이 없을 뿐.",
